import React, { useState, useEffect } from "react";
import { Container, Card, Button } from "react-bootstrap";

function Maps() {
  const [markers, setMarkers] = useState([]);
  const [showSidebar, setShowSidebar] = useState(false);

  useEffect(() => {
    fetch("http://localhost:3000/api/map-data")
      .then(res => res.json())
      .then(data => setMarkers(data))
      .catch(err => console.error(err));
  }, []);

  return (
    <Container fluid>
      <Card>
        <Card.Header>
          <Card.Title as="h4">📍 Bus Stop Locations</Card.Title>
          <p className="card-category">แสดงตำแหน่งป้ายรถจากฐานข้อมูล</p>
        </Card.Header>

        <Card.Body style={{ position: "relative" }}>

          {/* 🔘 ปุ่มขวาบน */}
          <Button
            variant="primary"
            style={{
              position: "absolute",
              top: "10px",
              right: "10px",
              zIndex: 1000,
            }}
            onClick={() => setShowSidebar(!showSidebar)}
          >
            ☰ รายละเอียด
          </Button>

          {/* 🗺 MAP */}
          <div style={{ height: "400px" }}>
            <iframe
              title="OpenStreetMap"
              width="100%"
              height="100%"
              frameBorder="0"
              src="https://www.openstreetmap.org/export/embed.html?bbox=99.89,19.02,99.91,19.04&layer=mapnik"
              style={{ borderRadius: "10px" }}
            />
          </div>

          {/* ⬅️ SIDEBAR */}
          <div
            style={{
              position: "absolute",
              top: 0,
              left: showSidebar ? 0 : "-300px",
              width: "300px",
              height: "100%",
              background: "#fff",
              boxShadow: "2px 0 10px rgba(0,0,0,0.2)",
              transition: "0.3s",
              padding: "15px",
              zIndex: 1200,
              overflowY: "auto",
            }}
          >
            <h5>🚌 Bus Stops</h5>
            <ul style={{ paddingLeft: "15px" }}>
              {markers.map((stop, index) => (
                <li key={index} style={{ marginBottom: "10px" }}>
                  <strong>{stop.Name}</strong><br />
                  👥 คนรอ: {stop.people || 0}
                </li>
              ))}
            </ul>
          </div>

        </Card.Body>
      </Card>
    </Container>
  );
}

export default Maps;
